code='''def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    key = [(r, c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] not in (0, 8)]
    blocks = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8]
    if not key or not blocks:
        return out
    kr0 = min(r for r,c,v in key); kr1 = max(r for r,c,v in key)
    kc0 = min(c for r,c,v in key); kc1 = max(c for r,c,v in key)
    keygrid = [[grid[r][c] for c in range(kc0,kc1+1)] for r in range(kr0,kr1+1)]
    br0 = min(r for r,c in blocks); br1 = max(r for r,c in blocks)
    bc0 = min(c for r,c in blocks); bc1 = max(c for r,c in blocks)
    bh, bw = br1-br0+1, bc1-bc0+1
    mask = {(r-br0,c-bc0) for r,c in blocks}
    variants=[]
    for flip in (False, True):
        a = [row[::-1] for row in keygrid] if flip else [row[:] for row in keygrid]
        for _ in range(4):
            variants.append(a)
            a = [list(row) for row in zip(*a[::-1])]
    for a in variants:
        ah, aw = len(a), len(a[0])
        if bh % ah or bw % aw or bh//ah != bw//aw:
            continue
        scale = bh//ah
        expanded = {(r*scale+dr,c*scale+dc) for r,row in enumerate(a) for c,v in enumerate(row) if v != 0 for dr in range(scale) for dc in range(scale)}
        if expanded != mask:
            continue
        for r,row in enumerate(a):
            for c,v in enumerate(row):
                if v:
                    for dr in range(scale):
                        for dc in range(scale):
                            out[br0+r*scale+dr][bc0+c*scale+dc]=v
        return out
    return out
'''
